<?php
require_once __DIR__ . '/../../includes/admin_auth.php'; require_admin();
$search = trim((string) ($_GET['q'] ?? ''));
$statement = $pdo->prepare('SELECT fees.id, fees.course_id, fees.fee_type, fees.amount, fees.discount_amount, fees.duration, fees.status, courses.title AS course_title FROM fees INNER JOIN courses ON courses.id = fees.course_id WHERE CONCAT_WS(" ", courses.title, fees.fee_type, fees.duration) LIKE :search ORDER BY fees.id DESC');
$statement->execute(['search' => '%' . $search . '%']); $fees = $statement->fetchAll(); admin_header('Fees', 'fees/index.php');
?><div class="d-flex flex-wrap gap-2 justify-content-between mb-3"><form class="d-flex gap-2" method="get"><input class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search fees..."><button class="btn btn-outline-secondary" type="submit"><i class="bi bi-search"></i></button></form><a href="create.php" class="btn btn-primary"><i class="bi bi-plus-lg me-1"></i>Add Fee</a></div><div class="card table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Course</th><th>Fee Type</th><th>Amount</th><th>Duration</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach ($fees as $fee): ?><tr><td><strong><?= e($fee['course_title']) ?></strong></td><td><?= e($fee['fee_type']) ?></td><td>Rs. <?= e(number_format((float) $fee['amount'], 2)) ?><small class="d-block text-success">Discount: Rs. <?= e(number_format((float) $fee['discount_amount'], 2)) ?></small></td><td><?= e($fee['duration']) ?></td><td><span class="badge text-bg-<?= $fee['status'] ? 'success' : 'secondary' ?>"><?= $fee['status'] ? 'Active' : 'Inactive' ?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?= e($fee['id']) ?>">Edit</a> <a class="btn btn-sm btn-outline-danger" href="delete.php?id=<?= e($fee['id']) ?>">Delete</a></td></tr><?php endforeach; ?><?php if (!$fees): ?><tr><td colspan="6" class="text-center text-secondary py-5">No fee records found.</td></tr><?php endif; ?></tbody></table></div></div><?php admin_footer(); ?>